        //  Dynamic Theme Manager 
        class DynamicThemeManager {
            constructor() {
                this.root = document.documentElement;
                this.auroraBlobs = document.querySelectorAll('.aurorabackground .aurora');
                this.colorPairs = [
                    { primary: '0A61F7', secondary: '39FF14' }, { primary: '39FF14', secondary: 'FFFF00' },
                    { primary: 'FFFF00', secondary: 'FF6B00' }, { primary: 'FF6B00', secondary: 'FF2D55' },
                    { primary: 'FF2D55', secondary: 'E51284' }, { primary: 'E51284', secondary: 'AF52DE' },
                    { primary: 'AF52DE', secondary: '0A61F7' }
                ];
                this.currentIndex = 0;
                this.updateColors();
                setInterval(() => this.cyclePalette(), 30000);
                setTimeout(() => this.auroraBlobs.forEach(b => b.classList.add('visible')), 500);
            }

            updateColors() {
                const pair = this.colorPairs[this.currentIndex];
                const primaryRGB = this.hexToRgb(pair.primary);
                this.root.style.setProperty('primary', pair.primary);
                this.root.style.setProperty('secondary', pair.secondary);
                this.root.style.setProperty('accent', pair.primary);
                this.root.style.setProperty('borderglow', rgba(${primaryRGB}, 0.5));
                this.auroraBlobs[0].style.backgroundColor = pair.primary;
                this.auroraBlobs[1].style.backgroundColor = pair.secondary;
            }

            hexToRgb(hex) {
                let r=0,g=0,b=0; if(hex.length==7){r=parseInt(hex.substring(1,3),16);g=parseInt(hex.substring(3,5),16);b=parseInt(hex.substring(5,7),16);} return ${r},${g},${b};
